import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import DialogOverview from "src/views/dialog/IT-Solution-Overview/DialogOverview";
import TableOverview from "src/views/tables/IT-Solution-Overview/TableOverview";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import DialogOverviewMainTitle from "src/views/dialog/IT-Solution-Overview/DialogOverviewMainTitle";
import DialogOverviewDownload from "src/views/dialog/IT-Solution-Overview/DialogOverviewDownload";
import TableOverviewMainTitle from "src/views/tables/IT-Solution-Overview/TableOverviewMainTitle";

const ITSolutionOverviewPage = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [overViewData, setOverViewData] = useState([]);
  const [featureTitle, setFeatureTitle] = useState([]);
  // const [pdfData, setPdfData] = useState([]);
  const [pdfData, setPdfData] = useState({});
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");

  const { id } = useParams(); // Get id from location.state
  const [overViewId, setOverViewId] = useState(
    id || localStorage.getItem("solutionId")
  );
  const [filteredData, setFilteredData] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  // Testimonials
  const [overViewFormDialogOpen, setOverViewFormDialogOpen] = useState(false);
  const [clientFormDialogMode, setClientFormDialogMode] = useState("add");
  const [clientCategoryToEdit, setClientCategoryToEdit] = useState(null);

  const [featureTitleDialogOpen, setFeatureTitleDialogOpen] = useState(false);
  const [featureTitleDialogMode, setFeatureTitleDialogMode] = useState("add");
  const [featureTitleToEdit, setFeatureTitleToEdit] = useState(null);
  const [uploadPdfDialogOpen, setUploadPdfDialogOpen] = useState(false);
  const [uploadPdfDialogMode, setUploadPdfDialogMode] = useState("add");
  const [uploadPdfToEdit, setUploadPdfToEdit] = useState(null);
  const [diableAddTitle, setDiableAddTitle] = useState(false);
  const [uploadPdfButtonVisible, setUploadPdfButtonVisible] = useState(true);
  const [deletePdfButtonVisible, setDeletePdfButtonVisible] = useState(false);

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [testimonialToDelete, setTestimonialToDelete] = useState(null);
  const [disableDeleteButton, setDisableDeleteButton] = useState(false);
  const [deleteType, setDeleteType] = useState("");
  const [featureTitleToDelete, setFeatureTitleToDelete] = useState(null);
  const [pdfToDelete, setPdfTodelete] = useState(null);

  const toggleRugFormDialog = (
    e,
    mode = "add",
    clientCategoryToEdit = null
  ) => {
    setOverViewFormDialogOpen((prev) => !prev);
    setClientFormDialogMode(mode);
    setClientCategoryToEdit(clientCategoryToEdit);
  };

  const toggleConfirmationDialog = (e, deletetype, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setTestimonialToDelete(dataToDelete);
    setDeleteType(deletetype);
    setPdfTodelete(dataToDelete);
    setFeatureTitleToDelete(dataToDelete);
    console.log("deletetype", deletetype);
    console.log("dataToDelete", dataToDelete);
  };
  const toggleFeatureTitleFormDialog = (
    e,
    mode = "add",
    featureTitleToEdit = null
  ) => {
    setFeatureTitleDialogOpen((prev) => !prev);
    setFeatureTitleDialogMode(mode);
    setFeatureTitleToEdit(featureTitleToEdit);
  };
  const toggleUploadPdfFormDialog = (
    e,
    mode = "add",
    featureTitleToEdit = null
  ) => {
    setUploadPdfDialogOpen((prev) => !prev);
    setUploadPdfDialogMode(mode);
    setUploadPdfToEdit(featureTitleToEdit);
  };
  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionOverview.list(overViewId), { params })
      .then((response) => {
        const responseData = response.data.data;
        setOverViewData(responseData);
        setFilteredData(responseData);
        setTotalCount(response.data.totalItems);
        if (responseData.length === 1) {
          setDisableDeleteButton(true);
        } else {
          setDisableDeleteButton(false); // Enable the button if there is no data
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchMainTitleData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewMainTitle.list(id))
      .then((response) => {
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setDiableAddTitle(true);
        } else {
          setDiableAddTitle(false); // Enable the button if there is no data
        }

        setFeatureTitle(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchPdfData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewDownload.list(id))
      .then((response) => {
        const responseData = response.data.data;
        // setPdfData(responseData);
        responseData.map((item) => setPdfData(item));
        if (responseData.length > 0) {
          setUploadPdfButtonVisible(false);
          setDeletePdfButtonVisible(true);
        } else {
          setUploadPdfButtonVisible(true);
          setDeletePdfButtonVisible(false);
        }
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  useEffect(() => {
    fetchMainTitleData();
    fetchPdfData();
  }, []);

  // const handleSearchChange = (e) => {
  //   if (searchTimeoutRef.current) {
  //     clearTimeout(searchTimeoutRef.current);
  //   }
  //   searchTimeoutRef.current = setTimeout(() => {
  //     setSearch(e.target.value);
  //   }, 500);
  // };

  // useEffect(() => {
  //   if (!search) {
  //     setOverViewData(overViewData);
  //   } else {
  //     const filtered = overViewData.filter((item) =>
  //       item.title.toLowerCase().includes(search.toLowerCase())
  //     );
  //     setOverViewData(filtered); // Set the filtered data
  //   }
  // }, [search, overViewData]);

  const handleSearchChange = (event) => {
    const value = event.target.value;
    setSearchTerm(value);

    // Filter overviewData based on searchTerm
    const filtered = overViewData.filter(
      (item) => item.title.toLowerCase().includes(value.toLowerCase()) // Assuming 'name' is the field to search
    );
    setFilteredData(filtered);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      const deleteUrl =
        deleteType === "deleteOverview"
          ? ApiEndPoints.ITSolutionOverview.delete(testimonialToDelete?.id)
          : deleteType === "delete details"
          ? ApiEndPoints.ITSolutionOverviewMainTitle.delete(
              featureTitleToDelete?.id
            )
          : ApiEndPoints.ITSolutionOverviewDownload.delete(pdfToDelete?.id);
      axiosInstance
        .delete(deleteUrl)
        .then((response) => response.data)
        .then((response) => {
          deleteType === "deleteOverview"
            ? fetchData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              })
            : deleteType === "delete details"
            ? fetchMainTitleData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              })
            : fetchPdfData();

          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, testimonialToDelete, pageSize, search]
  );
  const handleCellClick = (rowData) => {
    navigate(`/it-solution-sub-overview/${rowData.row.id}`, {
      state: rowData.row,
    });
  };
  const handleIconClick = () => {
    // navigate(`/it-solution-sublist/${id}`);
    navigate(-1);
  };
  return (
    <>
      <Grid container rowGap={10}>
        {" "}
        <Grid item container spacing={4} className="match-height">
          <PageHeader
            title={
              <Typography variant="h5">
                <Translations text="Overview Main Title " />
              </Typography>
            }
            action={
              <Button
                variant="contained"
                disabled={diableAddTitle}
                onClick={toggleFeatureTitleFormDialog}
              >
                Add Details
              </Button>
            }
          />
          <Grid item xs={12}>
            <Card>
              <Box sx={{ p: 5 }}>
                <TableOverviewMainTitle
                  loading={loading}
                  rows={featureTitle}
                  totalCount={totalCount}
                  setCurrentPage={setCurrentPage}
                  currentPage={currentPage}
                  setPageSize={setPageSize}
                  pageSize={pageSize}
                  toggleDelete={toggleConfirmationDialog}
                  toggleEdit={toggleFeatureTitleFormDialog}
                  toggleUploadPdf={toggleUploadPdfFormDialog}
                  uploadPdfButtonVisible={uploadPdfButtonVisible}
                  deletePdfButtonVisible={deletePdfButtonVisible}
                  pdfData={pdfData}
                />
              </Box>
            </Card>
          </Grid>
        </Grid>
        <Grid item container spacing={4} className="match-height">
          <PageHeader
            title={
              <Typography variant="h5">
                <Translations text="Overview" />
              </Typography>
            }
            action={
              <Button variant="contained" onClick={toggleRugFormDialog}>
                Add Overview
              </Button>
            }
            // backNavigation={
            //   <IconButton
            //     sx={{
            //       height: "30px",
            //       width: "30px",
            //       borderRadius: "50px",
            //       border: "2px solid #602de1c2",
            //       display: "flex",
            //       justifyContent: "center",
            //       alignItems: "center",
            //     }}
            //     onClick={handleIconClick}
            //   >
            //     <ArrowBackIcon sx={{ color: "#602de1c2", fontSize: "18px" }} />
            //   </IconButton>
            // }
          />
          <Grid item xs={12}>
            <Card>
              <Box
                sx={{
                  p: 5,
                  pb: 0,
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  justifyContent: "end",
                }}
              >
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
              <Box sx={{ p: 5 }}>
                <TableOverview
                  search={search}
                  loading={loading}
                  rows={filteredData}
                  totalCount={totalCount}
                  setCurrentPage={setCurrentPage}
                  currentPage={currentPage}
                  setPageSize={setPageSize}
                  pageSize={pageSize}
                  toggleDelete={toggleConfirmationDialog}
                  toggleEdit={toggleRugFormDialog}
                  onCellClick={(rowData) => handleCellClick(rowData)}
                  disableDeleteButton={disableDeleteButton}
                />
              </Box>
            </Card>
          </Grid>
        </Grid>
      </Grid>

      <DialogOverviewMainTitle
        mode={featureTitleDialogMode}
        open={featureTitleDialogOpen}
        toggle={toggleFeatureTitleFormDialog}
        dataToEdit={featureTitleToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchMainTitleData();
        }}
      />
      <DialogOverviewDownload
        mode={uploadPdfDialogMode}
        open={uploadPdfDialogOpen}
        toggle={toggleUploadPdfFormDialog}
        dataToEdit={uploadPdfToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchPdfData();
        }}
      />

      <DialogOverview
        mode={clientFormDialogMode}
        open={overViewFormDialogOpen}
        toggle={toggleRugFormDialog}
        itSolutionOverviewId={overViewId}
        dataToEdit={clientCategoryToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title={
          deleteType === "deleteOverview"
            ? "Delete Overview"
            : deleteType === "delete details"
            ? "Delete Details"
            : "Delete PDF"
        }
        subtitle={
          deleteType === "deleteOverview"
            ? "Are you sure you want to delete this Overview?"
            : deleteType === "delete details"
            ? "Are you sure you want to delete this Details?"
            : "Are you sure you want to delete this PDF?"
        }
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionOverviewPage;
